-- crash-edit/sources
-- A crash's sources for the editor: kind, link, how it relates, and when it was added. Witness statements are not included (private).
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/crash-edit.ts. Do not edit by hand.

select "sources"."id", "sources"."kind", "sources"."url", "crash_sources"."relation", "crash_sources"."created_at"
from "crash_sources"
inner join "sources" on "sources"."id" = "crash_sources"."source_id"
where "crash_sources"."crash_id" = $1
order by "crash_sources"."created_at";
